fn first_name(names: &[String]) -> Option<&str> {
    match names.first() {
        Some(name) => Some(name.as_str()),
        None => None,
    }
}

fn parse_positive(input: &str) -> Result<u32, String> {
    let value = input.parse::<u32>().map_err(|error| error.to_string())?;
    if value == 0 { return Err(String::from("count must be positive")); }
    Ok(value)
}
